  const PUBLICS = [['proprietaires', 'Propriétaires'], ['locataires', 'Locataires'], ['tous', 'Propriétaires et locataires']];
  const pubNom = k => (PUBLICS.find(p => p[0] === k) || [])[1] || k;
  const LONG = [['court', 'Court, 400 mots', 400], ['moyen', 'Moyen, 800 mots', 800], ['long', 'Long, 1 200 mots', 1200]];
